CREATE TABLE IF NOT EXISTS continental_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_code text NOT NULL UNIQUE, asset_name text NOT NULL, asset_type text NOT NULL, jurisdiction_id uuid, country_code text, region text, locality text, geographic_reference text, project_reference text, owner_entity_reference text, beneficial_owner_reference text, ownership_status text NOT NULL DEFAULT 'Unverified', title_status text NOT NULL DEFAULT 'Unverified', customary_rights_status text NOT NULL DEFAULT 'Unreviewed', community_rights_status text NOT NULL DEFAULT 'Unreviewed', environmental_status text NOT NULL DEFAULT 'Unreviewed', mineral_rights_status text NOT NULL DEFAULT 'Not Applicable', carbon_rights_status text NOT NULL DEFAULT 'Not Applicable', encumbrance_status text NOT NULL DEFAULT 'Unknown', valuation_status text NOT NULL DEFAULT 'Not Valued', diligence_status text NOT NULL DEFAULT 'Not Started', investment_status text NOT NULL DEFAULT 'Not Investment Ready', evidence_status text NOT NULL DEFAULT 'Unverified', status text NOT NULL DEFAULT 'Draft', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asset_titles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, title_type text NOT NULL, title_number text, issuing_authority text, holder_reference text, issue_date date, expiry_date date, geographic_reference text, status text NOT NULL DEFAULT 'Unverified', evidence_reference text, verification_method text, verified_by text, verified_date date);
CREATE TABLE IF NOT EXISTS asset_ownership_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, owner_type text NOT NULL, owner_reference text NOT NULL, ownership_percentage numeric(8,4), beneficial_owner_reference text, instrument_reference text, effective_date date, verification_status text NOT NULL DEFAULT 'Unverified', evidence_reference text, notes text);
CREATE TABLE IF NOT EXISTS asset_encumbrances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, encumbrance_type text NOT NULL, holder_reference text, instrument_reference text, amount_reference text, priority text, registered_date date, release_date date, status text NOT NULL DEFAULT 'Unverified', evidence_reference text);
CREATE TABLE IF NOT EXISTS asset_rights_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, stewardship_right_id uuid REFERENCES stewardship_rights(id), community_id uuid REFERENCES stewardship_communities(id), right_type text NOT NULL, impact_level text NOT NULL DEFAULT 'Unknown', review_status text NOT NULL DEFAULT 'Pending', clearance_reference uuid REFERENCES stewardship_clearances(id), evidence_reference text);
CREATE TABLE IF NOT EXISTS asset_environmental_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, review_type text NOT NULL, authority_reference text, assessment_reference text, permit_reference text, impact_status text NOT NULL DEFAULT 'Unreviewed', mitigation_status text NOT NULL DEFAULT 'Unreviewed', conditions text, expiry_date date, evidence_reference text, status text NOT NULL DEFAULT 'Pending');
CREATE TABLE IF NOT EXISTS asset_mineral_rights (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, mineral_type text NOT NULL, rights_holder_reference text, licence_reference text, licence_type text, area_reference text, term_start date, term_end date, status text NOT NULL DEFAULT 'Unverified', evidence_reference text);
CREATE TABLE IF NOT EXISTS asset_carbon_rights (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, carbon_project_reference text, rights_holder_reference text, methodology text, registry_reference text, credit_status text NOT NULL DEFAULT 'Unverified', issuance_status text NOT NULL DEFAULT 'Not Issued', verification_body text, evidence_reference text);
CREATE TABLE IF NOT EXISTS asset_valuations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, valuation_type text NOT NULL, valuation_amount numeric(24,4), currency text, valuation_date date, valuer_reference text, methodology text, assumptions text, confidence_score numeric(5,2), evidence_reference text, status text NOT NULL DEFAULT 'Unverified');
CREATE TABLE IF NOT EXISTS asset_due_diligence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, diligence_type text NOT NULL, reviewer_reference text, scope text, findings text, risk_rating text NOT NULL DEFAULT 'Unrated', outstanding_items text, completed_date date, evidence_reference text, status text NOT NULL DEFAULT 'Open');
CREATE TABLE IF NOT EXISTS asset_investment_vehicles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, vehicle_type text NOT NULL, vehicle_name text NOT NULL, entity_reference text, jurisdiction_code text, ownership_structure text, securities_status text NOT NULL DEFAULT 'Not Applicable', approval_status text NOT NULL DEFAULT 'Proposed', evidence_reference text, status text NOT NULL DEFAULT 'Proposed');
CREATE TABLE IF NOT EXISTS asset_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, evidence_type text NOT NULL, reference text NOT NULL, source_description text, authority_level text NOT NULL DEFAULT 'Unknown', verification_status text NOT NULL DEFAULT 'Unverified', confidence_score numeric(5,2), verified_by text, verified_date date, hash_reference text, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asset_readiness_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, review_version text NOT NULL, ownership_gate text NOT NULL DEFAULT 'Pending', title_gate text NOT NULL DEFAULT 'Pending', rights_gate text NOT NULL DEFAULT 'Pending', environmental_gate text NOT NULL DEFAULT 'Pending', encumbrance_gate text NOT NULL DEFAULT 'Pending', valuation_gate text NOT NULL DEFAULT 'Pending', diligence_gate text NOT NULL DEFAULT 'Pending', legal_gate text NOT NULL DEFAULT 'Pending', investment_readiness text NOT NULL DEFAULT 'Not Ready', reviewer_reference text, decision_basis text, evidence_reference text, reviewed_date date, status text NOT NULL DEFAULT 'Draft');
CREATE INDEX IF NOT EXISTS idx_assets_country ON continental_assets(country_code);
CREATE INDEX IF NOT EXISTS idx_assets_type ON continental_assets(asset_type);
CREATE INDEX IF NOT EXISTS idx_asset_evidence_asset ON asset_evidence(asset_id);